-- One-time Kosykin editorial release. No credentials or operational settings change.
-- Previous legal sections stay in the CMS, hidden rather than deleted.
-- Existing FAQ questions are retained; duplicate questions are not added.
DO $phase6$
DECLARE
  store_id uuid;
  page_id uuid;
  page jsonb;
  section jsonb;
  position integer;
  page_position integer := 0;
  faq_items jsonb;
BEGIN
  SELECT id INTO store_id FROM "Store" WHERE slug = 'kosykin';
  IF store_id IS NULL THEN RETURN; END IF;
  -- Identity supplied by the business owner (ABN Lookup screenshot, 11 Oct 2026).
  UPDATE "Store" SET "legalName" = 'FORERO GUTIERREZ, YULIANY ROCIO',
    organization = organization || '{"abn":"84884117384","registeredBusinessName":"Tapkin","gstRegistered":false}'::jsonb,
    "updatedAt" = CURRENT_TIMESTAMP WHERE id = store_id;
  FOR page IN SELECT value FROM jsonb_array_elements($content$[{"slug":"terms","name":"Terms and conditions","description":"Kosykin Australian purchase terms: orders, custom designs, delivery, cancellations, consumer guarantees, accounts and customer points.","sections":[{"name":"About these terms","type":"RICH_TEXT","content":{"headline":"About these terms","copy":"Updated 11 October 2026. Kosykin is a homewares brand operated under Tapkin. The legal seller and Australian Business Number are shown above. These terms apply to purchases through this Australian store, together with the product description, options selected and any custom quote accepted before payment. Our privacy, shipping, returns, custom-design and points pages explain the relevant processes. Optional services apply only when they are available. Prices and order details shown before payment form part of your purchase.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Your Australian consumer rights","type":"RICH_TEXT","content":{"headline":"Your Australian consumer rights","copy":"Nothing in these terms excludes, restricts or modifies rights or remedies that cannot lawfully be excluded, including under the Australian Consumer Law. Products must meet applicable consumer guarantees, including acceptable quality, correspondence with their description and fitness for a purpose you tell us about and we accept. These protections also apply to personalised, made-to-order and discounted goods. A stated product warranty is additional to, and does not replace, these rights.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Choosing products and using them safely","type":"RICH_TEXT","content":{"headline":"Choosing products and using them safely","copy":"Check the individual listing for dimensions, material, finish, compatibility, included parts, intended use and care instructions before ordering. Layer lines and slight colour differences may be normal features of 3D printing where accurately described; they do not excuse defects or a material mismatch with the description. Do not assume an item is food-contact safe, dishwasher safe, waterproof, heat resistant, a toy, suitable for infants, electrically certified or suitable for heavy loads unless its listing expressly supports that use. Tell us about a particular purpose before buying if you need advice.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Prices, payment and availability","type":"RICH_TEXT","content":{"headline":"Prices, payment and availability","copy":"Prices are in Australian dollars. Any GST applicable to the sale is included in the displayed consumer price. Delivery and any selected paid options are shown before payment. Stripe processes payment using the methods offered at checkout; we do not store full card details. A pending checkout or payment receipt alone does not mean an item has shipped. We confirm payment and order progress separately. If checkout is closed, a product is unavailable or an address cannot be served, an order cannot be completed through that checkout.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Order acceptance and genuine mistakes","type":"RICH_TEXT","content":{"headline":"Order acceptance and genuine mistakes","copy":"Check the product, quantity, personalisation, email and delivery address before paying. We may need to review a custom request, stock availability, a suspected payment problem or a clear pricing error before accepting or making the order. We will contact you through your verified ticket channel if a paid order cannot be supplied as agreed, explain the issue and offer an appropriate alternative for you to accept or a refund. We will not charge a higher price or substitute a materially different product without your agreement. We do not reserve a blanket right to cancel an accepted order at our discretion.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Personalisation and customer designs","type":"RICH_TEXT","content":{"headline":"Personalisation and customer designs","copy":"You are responsible for checking spelling, names, dimensions and other instructions that you provide. Submit only files and designs you own or have permission to use for the intended purpose. Our Custom designs page explains the limited permission you give us to review and manufacture your request. A request is not an accepted custom job until we confirm feasibility, price, scope and any relevant timing. Responsibility for your instructions does not remove our obligation to supply what we agreed or meet consumer guarantees.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Production, changes and cancellation requests","type":"RICH_TEXT","content":{"headline":"Production, changes and cancellation requests","copy":"We accept a change-of-mind cancellation when manufacturing or preparation has not started. Submit a verified cancellation request promptly through Help & requests. Eligible requests can pause the order while we review it; check the ticket for confirmation. A request or pause is not itself a confirmed cancellation or refund. Once preparation or manufacturing has started, we do not offer change-of-mind cancellation, and changes may be unavailable. This restriction does not apply to a remedy you are legally entitled to for a failure, misleading description or other breach. We will not use a slow ticket response to disregard a request received while the order was still eligible.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Delivery and order tracking","type":"RICH_TEXT","content":{"headline":"Delivery and order tracking","copy":"We deliver to eligible Australian addresses supported at checkout. Production time and carrier transit time are separate. Any timing supplied is an estimate unless expressly agreed as a commitment. Shippit and the relevant carrier receive the information needed for delivery and supply tracking updates. Creation of a label does not mean the carrier has collected your parcel. Contact us about missing, damaged or significantly delayed parcels; we remain responsible for addressing your purchase and will not require you to resolve our delivery obligations with the carrier alone.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Returns and remedies","type":"RICH_TEXT","content":{"headline":"Returns and remedies","copy":"We do not offer returns or exchanges solely because you changed your mind, chose the wrong size where the listing was accurate, or no longer want the item. This is separate from eligible pre-production cancellation. For a faulty, unsafe, wrongly supplied or materially misdescribed item, use Help & requests and describe the problem. We may reasonably assess it. For a major failure, available rights include choosing a refund or replacement; for a minor failure, we must provide an appropriate remedy within a reasonable time. Compensation may also be available under law. See Returns & cancellations for return handling.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Accounts and verified guest access","type":"RICH_TEXT","content":{"headline":"Accounts and verified guest access","copy":"You may buy as a guest when checkout is available. An account can provide order history, saved addresses and other enabled features. Keep your password and verification codes confidential and tell us if you suspect unauthorised access. Email sign-in remains available; Google sign-in and, if enabled, Apple sign-in involve their respective provider. Guest ticket access requires verification of the relevant email. An account is not required to exercise consumer rights. For accessibility or lost access problems, the help page explains how to request assistance.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Customer points and promotions","type":"RICH_TEXT","content":{"headline":"Customer points and promotions","copy":"If enabled, customer points are a promotional discount on eligible future purchases, not money, a purchased gift card or a transferable balance. Earning, redemption, expiry, refunds and programme changes are explained on our Customer points page and in your account. The applicable checkout rules are recorded with the order. Offer eligibility and any limits are shown before payment. Mandatory consumer remedies are never replaced by store credit or points without your agreement.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Customer service and complaints","type":"RICH_TEXT","content":{"headline":"Customer service and complaints","copy":"Our customer service channel is the website ticket system: Account → Help & requests, or verified guest access on the help page. Our initial response target is five business days, excluding weekends and store holidays in Australia/Adelaide; this is not a guaranteed resolution time and does not limit legal rights. Keep related messages in the same ticket. Email notifications direct you back to it; replies to outgoing notification emails are not monitored. Social media is not a verified order-support channel. Ask us to review an unresolved complaint in your ticket; you may also seek help from your state or territory consumer protection agency.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Website content and acceptable use","type":"RICH_TEXT","content":{"headline":"Website content and acceptable use","copy":"Our site content and designs are protected by applicable intellectual-property rights. You may use the site for personal shopping and ordinary product research. Do not misuse accounts, scrape private customer information, submit malicious files, impersonate others, evade security controls or use the service for unlawful activity. We may proportionately restrict misuse or a compromised account to protect customers, explain the reason where safe and allow a review. Restrictions do not remove your existing order entitlements or lawful access requests.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Limits, changes and disputes","type":"RICH_TEXT","content":{"headline":"Limits, changes and disputes","copy":"We do not exclude liability that Australian law does not allow us to exclude, or require you to indemnify us for our own negligence or breach. Liability and compensation are determined under applicable law, not a blanket purchase-price cap. Updated terms apply to future purchases; they do not retrospectively remove rights from an accepted order. If a term cannot be enforced, the remaining lawful terms continue. Applicable Australian law governs, and you retain access to courts, tribunals and consumer agencies available to you; these terms do not require you to litigate only in our home state.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}}]},{"slug":"privacy","name":"Privacy policy","description":"How Kosykin handles account, order, address, ticket and points information, optional browser storage, analytics and privacy requests in Australia.","sections":[{"name":"Who we are and what this policy covers","type":"RICH_TEXT","content":{"headline":"Who we are and what this policy covers","copy":"Updated 11 October 2026. Kosykin is operated under Tapkin. This policy describes information handled through this store, its customer accounts, orders and support tickets. It also covers optional services if they are enabled. We follow the requirements of privacy law that apply to us. Some Australian small businesses are exempt from parts of the Privacy Act, while exceptions can make that Act applicable; this policy does not claim an exemption or remove rights you have. Contact us about privacy through Help & requests, using verified guest access if you do not have an account.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Information you provide","type":"RICH_TEXT","content":{"headline":"Information you provide","copy":"We handle your name, email, phone number and delivery details when you enter them for an order, account or support request. Orders include products, selected options, personalisation, prices, payment references and delivery progress. Account features may store addresses, favourites, saved carts, preferences, authentication-provider links and customer points activity. Tickets include the issue, replies and information you choose to share. Custom requests may include measurements, artwork or design files if we accept them. Do not include unnecessary sensitive information, identity documents, full card details or details about other people without authority.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Technical information and where it comes from","type":"RICH_TEXT","content":{"headline":"Technical information and where it comes from","copy":"The site and its service providers process information such as IP addresses, browser/device information, request logs, security events, session identifiers and timestamps to operate and protect the service. We obtain information from you, authentication providers you choose, payment confirmation from Stripe, delivery information from Shippit and carriers, and consented measurement services if enabled. We do not seek sensitive personal information for ordinary homewares purchases. If a request requires additional verification, we ask only for what is reasonably needed.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Why we use information","type":"RICH_TEXT","content":{"headline":"Why we use information","copy":"We use information to process and fulfil orders, communicate payment and delivery progress, manufacture agreed personalisation, authenticate accounts and guests, manage customer points, answer tickets, detect abuse and meet record-keeping or legal requirements. You can browse without an account. If you do not supply information necessary for a particular transaction, we may be unable to complete it or verify a request. Optional marketing and measurement choices are separate from making a purchase or obtaining support.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Accounts and sign-in providers","type":"RICH_TEXT","content":{"headline":"Accounts and sign-in providers","copy":"Email accounts use password hashes rather than readable passwords, and verification or recovery messages are sent to your email. If you choose Google sign-in, we receive the identity details needed to authenticate you, such as a provider identifier, email and name; Google handles its own sign-in page under its policy. Apple is used only if offered and selected. We do not request access to your mailbox, contacts or unrelated provider content for sign-in. Profile editing does not directly change your login email; contact support about identity or access corrections.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Cookies, local storage and remembering checkout","type":"RICH_TEXT","content":{"headline":"Cookies, local storage and remembering checkout","copy":"Essential cookies and similar storage support sessions, carts, security and your privacy preferences. If offered and you explicitly select Remember my details, contact and delivery details are saved in this browser with an expiry of up to 90 days under the current setting; no card details are included. Expired details are not reused and are removed when checkout next reads them; an inactive browser can retain the stored entry until then or until you clear it. This local storage is different from a server account and is specific to the device and browser. You can use Forget saved details or clear site storage. Do not opt in on a shared device. Saved account addresses are separate and remain until removed or otherwise handled through an account request.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Australian address suggestions","type":"RICH_TEXT","content":{"headline":"Australian address suggestions","copy":"Geoapify address suggestions are optional and operate only when enabled for this store. Queries are filtered to Australia. The part of the address you type is sent through our server to Geoapify so it can suggest addresses; other checkout fields are not included in the suggestion query. Selecting a suggestion can populate address fields, but you must check unit numbers and the final address. Manual entry remains available. Geoapify processes queries under its own service terms and privacy policy.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Google Analytics and Microsoft Clarity","type":"RICH_TEXT","content":{"headline":"Google Analytics and Microsoft Clarity","copy":"If enabled, Google Analytics 4 receives consented shopping and website events to help us understand visits and purchases. Microsoft Clarity may record consented, anonymous browsing of home, shop, FAQ and policy pages with text masked. Our Clarity integration excludes checkout, personalisation, accounts, orders, support tickets, administration and NFC profiles. These tools remain inactive when not configured or enabled and require analytics consent. Masking and exclusions reduce exposure but are not a promise that no technical identifiers are processed by the provider.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Meta advertising and product catalogues","type":"RICH_TEXT","content":{"headline":"Meta advertising and product catalogues","copy":"If enabled and you allow advertising measurement, Meta Pixel and Conversions API receive selected website and confirmed-purchase events, including product identifiers, amounts, currency and event identifiers used to avoid duplication. Browser or advertising identifiers can also be involved. We do not send names, customer contact details, addresses or personalisation text through our shopping measurement integration or enable customer-contact advanced matching. A Meta catalogue feed contains public product information and is separate from customer event tracking. These services do not run merely because this policy describes them.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Your measurement and marketing choices","type":"RICH_TEXT","content":{"headline":"Your measurement and marketing choices","copy":"Use Privacy & cookie settings to allow or decline optional analytics and advertising or change your choice later. Declining does not prevent a purchase or support request. Withdrawal stops future optional collection through our integration; it does not recall information already received by a provider. Browser blocking and provider settings may also limit tracking. Marketing email is a separate opt-in preference, not a condition of ordering. We identify the sender and provide an unsubscribe route in commercial messages, honouring unsubscribe requests within five working days. Essential account, order and ticket messages can still be sent for their service purpose.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Service providers and sharing","type":"RICH_TEXT","content":{"headline":"Service providers and sharing","copy":"We share only information reasonably needed with providers supporting hosting and storage (including Microsoft Azure), payment (Stripe), transactional email (Resend), address suggestions (Geoapify when enabled), shipping (Shippit and the selected carrier) and the optional measurement services described above. Our authorised team accesses information for fulfilment, customer service and administration according to their role. We may disclose information where required by law, to address a safety issue or to establish or defend a legitimate legal claim. We do not publish private orders, tickets or customer designs as marketing material without separate permission.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Overseas processing","type":"RICH_TEXT","content":{"headline":"Overseas processing","copy":"Some providers and their subprocessors process or store information outside Australia. Countries can include the United States and countries in the European Union, depending on the provider, service and configuration; Australian hosting does not make every provider Australian-only. We consider appropriate contracts, security and applicable overseas-disclosure obligations. Ask through a privacy ticket for current provider and location information relevant to your data. A provider’s own account, payment or sign-in service may also collect information directly under its own privacy policy.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Customer points and related brands","type":"RICH_TEXT","content":{"headline":"Customer points and related brands","copy":"Points use a store-specific ledger of earning, expiry, redemption and refund adjustments. Guest purchases can be associated with a protected email-derived identifier and claimed after verification of that email. A hash reduces direct exposure but does not make linked purchase information anonymous. Kosykin and Tapkin operate on a shared platform: account identity and saved delivery addresses can be shared platform features, while order access, customer points and store preferences are scoped to the relevant store. Points are not automatically transferable between brands.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Retention, security and deletion","type":"RICH_TEXT","content":{"headline":"Retention, security and deletion","copy":"We retain information for the purpose for which it is needed, including fulfilment, support, disputes, security and applicable tax or legal record keeping. Some business records generally need to be kept for at least five years, and certain records require longer. The optional remembered-checkout period applies to browser details, not all order records. Customer design files are kept as reasonably needed for the agreed job and follow-up; request removal when no longer needed. Expired points do not automatically erase the audit ledger. Access controls and secure transport protect data, but no service can guarantee absolute security. A deletion request is reviewed; records we must retain may be restricted instead of immediately erased.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Access, correction and complaints","type":"RICH_TEXT","content":{"headline":"Access, correction and complaints","copy":"You can edit permitted account details and addresses, manage marketing preferences and download available account information. You can request access, correction, deletion or an explanation through a privacy ticket, including as a verified guest. We reasonably verify your identity before disclosing or changing information. If we cannot fulfil a request in full, we explain why and any available review route. Our initial ticket response target is five business days; a complex privacy request or complaint may take longer. If unresolved, you can contact the OAIC where it has jurisdiction or another relevant regulator. You do not waive legal complaint rights by using our ticket channel.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Children, safety incidents and policy updates","type":"RICH_TEXT","content":{"headline":"Children, safety incidents and policy updates","copy":"The store is not intended to solicit accounts or personal data from children. An adult responsible for an order should provide their own contact details and avoid unnecessary information about a child. Tell us if information was supplied without appropriate authority. We assess suspected security incidents and, where legally required, notify affected people and the relevant regulator. We update this policy when practices change and show the revised date. A policy update is not consent to new optional tracking or marketing.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}}]},{"slug":"shipping-delivery","name":"Shipping & delivery","description":"Australian delivery, production timing, address checks, parcel tracking and help with delayed, missing or damaged Kosykin orders.","sections":[{"name":"Where we deliver","type":"RICH_TEXT","content":{"headline":"Where we deliver","copy":"Available delivery options are shown for your Australian address at checkout. Availability depends on the product, parcel and carrier service; do not assume every postcode, PO box or parcel locker is supported. Ask through Help & requests before ordering if the address needs special handling. International delivery is not offered through the current Australian checkout.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Costs and timing","type":"RICH_TEXT","content":{"headline":"Costs and timing","copy":"The shipping charge and any eligible free-shipping offer are shown before payment. Production or preparation time is separate from carrier transit time. Consult the listing and any accepted quote for the estimate relevant to your item. We do not promise same-day dispatch or a fixed arrival date unless expressly agreed. If you need an item for an event, check feasibility before paying. If a material delay develops, we will explain available options and preserve remedies available under law.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Check the delivery address","type":"RICH_TEXT","content":{"headline":"Check the delivery address","copy":"Check the recipient, street or unit number, suburb, state, postcode and phone details before payment, even when selecting an address suggestion. Request an address change promptly through the verified order ticket. We will confirm whether the change is still possible and any genuine additional cost before proceeding. Once a parcel is booked or collected, a carrier redirection may be unavailable. We assess failed-delivery or redelivery costs according to the circumstances and your legal rights, rather than automatically charging every case.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Labels, collection and tracking","type":"RICH_TEXT","content":{"headline":"Labels, collection and tracking","copy":"A shipping label can be prepared before your order is ready. It does not mean the parcel has left us. The carrier is booked when the parcel is ready; Shippit and carrier updates then inform shipped and delivered tracking. Check your order’s tracking link for the latest available information. Updates can arrive late or describe only one parcel in a multi-parcel order. A delivered scan is evidence to investigate, not conclusive proof against a missing-parcel claim.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Delivery problems","type":"RICH_TEXT","content":{"headline":"Delivery problems","copy":"If a parcel is missing, damaged, incorrectly delivered or significantly delayed, open a Delivery ticket with your order number and what happened. Photos of packaging or damage can help if available, but we do not impose an arbitrary deadline or require evidence you cannot reasonably provide. We will investigate with the carrier and arrange the appropriate outcome. We do not exclude responsibility merely because a parcel was handed to a carrier or insured.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Returns and safety","type":"RICH_TEXT","content":{"headline":"Returns and safety","copy":"Please do not send an item back to an unconfirmed address. Use Help & requests for return instructions. Our Returns & cancellations page explains return costs and remedies for faulty goods. If the item appears unsafe, stop using it and tell us promptly; contact emergency services directly for an emergency. Our normal ticket-response target does not defer any safety or legal obligations.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}}]},{"slug":"returns-cancellations","name":"Returns & cancellations","description":"Kosykin change-of-mind policy, cancellation before production, Australian consumer guarantees and return instructions for faulty products.","sections":[{"name":"Change-of-mind returns","type":"RICH_TEXT","content":{"headline":"Change-of-mind returns","copy":"We do not accept returns or exchanges solely for a change of mind after preparation or manufacturing has started. This includes accurately supplied personalised and made-to-order items. Before that stage, we accept a change-of-mind cancellation through a verified request. These rules do not exclude remedies for faulty, unsafe, wrongly supplied or materially misdescribed products, or other rights under Australian law.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Cancel or change before preparation starts","type":"RICH_TEXT","content":{"headline":"Cancel or change before preparation starts","copy":"Open an order-specific Cancellation request or Order change ticket as soon as possible. An eligible verified request can pause preparation while reviewed. Keep the acknowledgement and check the ticket for the decision; submitting a request is not the same as a confirmed cancellation or refund. We assess eligibility at the time the verified request reaches us, not merely when we read it. If work has already started, we explain that status and whether a change can still be agreed. No change-of-mind fee is imposed for an accepted eligible cancellation.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"If your item has a problem","type":"RICH_TEXT","content":{"headline":"If your item has a problem","copy":"Tell us what went wrong through a Quality or Delivery ticket, quoting the order number or other reasonable proof of purchase. Helpful details include the item, when you noticed the issue and photos if practical. We can assess the product to identify the problem. You do not need the original packaging to exercise consumer guarantee rights. We do not set a blanket short return window for defects or exclude sale and customised items.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Major and minor failures","type":"RICH_TEXT","content":{"headline":"Major and minor failures","copy":"For a major product failure, you may choose a refund or replacement and may have other rights, including compensation. For a minor problem, we provide an appropriate remedy within a reasonable time; further remedies apply if we cannot do so. We do not deduct for ordinary use when a full refund is legally due, force a voucher instead of a monetary refund or send you to a manufacturer to resolve our obligations. Any custom design service is also subject to applicable service guarantees.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Return instructions and reasonable costs","type":"RICH_TEXT","content":{"headline":"Return instructions and reasonable costs","copy":"Contact us for a confirmed return address and instructions before posting. You can return reasonably portable items as arranged; where a fault is confirmed, we reimburse reasonable return postage. We arrange collection or cover reasonable transport for items that are too large or difficult to return. No restocking or processing fee is charged for a remedy you are entitled to for a faulty item. If assessment finds no failure covered by law, we explain any proposed reasonable cost and obtain your agreement in advance rather than applying a surprise charge.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Refunds and customer points","type":"RICH_TEXT","content":{"headline":"Refunds and customer points","copy":"We normally return money through the original payment method unless you agree otherwise. Payment-provider processing time can vary; we confirm the refund status rather than promising a particular bank settlement date. Points earned or used on a refunded order are adjusted under the Customer points rules, with their original expiry where applicable. This accounting does not reduce a mandatory cash remedy or replace it with points without your agreement.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Getting help or escalating","type":"RICH_TEXT","content":{"headline":"Getting help or escalating","copy":"Use Account → Help & requests or the verified guest help route. Our first-response target is five business days, not a mandatory waiting period before exercising your rights. Request a review in the same ticket if the response does not resolve your issue. You may seek help from the relevant consumer protection agency or pursue a lawful dispute route. If an item is unsafe, stop using it and flag that in your ticket; emergencies should go directly to emergency services.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}}]},{"slug":"custom-designs","name":"Custom designs & customer files","description":"Requesting custom 3D-printed Kosykin homewares: design review, customer file permissions, agreed specifications, privacy and product safety.","sections":[{"name":"A request comes before a custom order","type":"RICH_TEXT","content":{"headline":"A request comes before a custom order","copy":"You may ask us about a customer design or file through Help & requests. Acceptance depends on our ability to review and manufacture it safely and lawfully. The available upload method, supported format, size and any design fee must be agreed for that job; do not assume every file can be uploaded through checkout. We confirm scope, price, material, dimensions, finishing, quantity and estimated timing before you accept a custom quote. A conversation or file submission alone does not commit you to a charge.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Permission to use your design","type":"RICH_TEXT","content":{"headline":"Permission to use your design","copy":"You retain rights you own in files you submit. You confirm that you own or have permission to use the design, logos, images, names and other content for the requested manufacture and supply. You give us a limited permission to inspect, adapt as agreed, print and handle the files for your job and related support. This is not a transfer of ownership or a licence to sell your design to others. Any ownership or licence for newly commissioned design work is stated in the accepted quote, not assumed.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Reviewing specifications and proofs","type":"RICH_TEXT","content":{"headline":"Reviewing specifications and proofs","copy":"Tell us the intended use, dimensions, fit, load and environmental conditions that matter. We will identify assumptions and significant changes in the quote or proof. Check spelling, layout and agreed specifications carefully before approving manufacture. Screen images and renders are guides, not a guarantee of an exact finish or colour. An approved proof does not excuse our printing a different design or supplying a faulty product.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"What we cannot accept","type":"RICH_TEXT","content":{"headline":"What we cannot accept","copy":"We may decline content that appears to infringe rights, breaches law, contains malware, invades another person’s privacy or requests unsafe or prohibited products. We do not promise to manufacture weapons, regulated items, safety-critical components, electrical parts, medical devices or children’s products through an ordinary homewares custom request. Suitability, any mandatory standards and any required professional assessment must be resolved before a relevant product is offered. We explain a declined request where reasonably possible.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Confidentiality and file handling","type":"RICH_TEXT","content":{"headline":"Confidentiality and file handling","copy":"Share only information needed for the job, and discuss a confidentiality requirement before submitting commercially sensitive designs. Authorised team members and necessary storage or production providers may handle accepted files for that purpose. We do not use customer artwork or finished personalised items in public marketing without separate permission. Ask for deletion when files are no longer needed; relevant order, permission and dispute records may need to be retained. Our Privacy policy describes security and request handling.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Changes and cancellation","type":"RICH_TEXT","content":{"headline":"Changes and cancellation","copy":"We accept an eligible cancellation before manufacturing or preparation starts. Use a verified ticket promptly and wait for confirmation. After work starts, a change or change-of-mind cancellation may not be possible. Any additional design work, material or production charge for an agreed change is explained for your acceptance first. No approval, intellectual-property clause or custom-order condition takes away your Australian consumer guarantees.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Care and responsibility for the finished product","type":"RICH_TEXT","content":{"headline":"Care and responsibility for the finished product","copy":"Use the item only for its agreed or described purpose and follow the supplied care information. Do not assume a particular material, temperature limit, food-contact suitability or load rating without confirmation. Tell us promptly about a safety concern or a mismatch with the agreed specifications. We remain responsible for applicable consumer guarantees for goods and any design services we supply.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}}]},{"slug":"customer-points","name":"Customer points","description":"How Kosykin customer points are earned, claimed, redeemed and expired, including guest purchases, refunds and store-specific programme rules.","sections":[{"name":"How points work","type":"RICH_TEXT","content":{"headline":"How points work","copy":"When the programme is enabled, eligible paid orders earn store-specific points. Current earning and redemption rates, minimums, discount caps and offer-combination rules are shown in your account and at checkout. Check them before paying. The programme is a promotional reward, not a paid gift card, bank balance or entitlement to withdraw cash. Points cannot be transferred to another person or automatically used at another brand. A paused programme stops new earning and redemption while existing history and expiry remain visible.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Earning and claiming","type":"RICH_TEXT","content":{"headline":"Earning and claiming","copy":"Points are credited only after confirmed payment, based on eligible merchandise after discounts, excluding shipping. Fractions are rounded down to whole points under the checkout rules. Cancelled or failed payments do not earn points. Guests can earn when eligible and claim by verifying the purchase email; using a different email does not automatically merge balances. There is no automatic credit for purchases made before the programme started. Ask through Help & requests about a missing credit or an identity issue.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Redeeming at checkout","type":"RICH_TEXT","content":{"headline":"Redeeming at checkout","copy":"Redemption requires a verified account, sufficient available points and an eligible checkout. Points are used in the configured units and cannot cover more than the applicable merchandise discount cap or pay shipping. Unless the current rules expressly permit it, points cannot be combined with another promotional discount. Pending checkouts reserve points so they cannot be spent twice. An abandoned payment can remain reserved until the payment provider confirms cancellation or expiry; contact us about an unexpectedly persistent reservation.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Expiry","type":"RICH_TEXT","content":{"headline":"Expiry","copy":"Each award has an expiry date calculated from confirmed payment under the rules recorded with that purchase. Check the dated balances in your account. Under the initial programme setting, awards last 12 calendar months; later purchases may use a different disclosed setting. Changing future programme settings does not rewrite the recorded rules on an existing order. Removing a checkout reservation does not revive points whose original expiry has already passed.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Refund adjustments","type":"RICH_TEXT","content":{"headline":"Refund adjustments","copy":"Confirmed cash refunds reverse points earned on the refunded order and return redeemed points proportionally, retaining their original expiry. Because partial refunds are currently recorded as amounts rather than item allocations, the proportion uses cumulative cash refunded divided by the original cash total, including delivery charges. If returned points have already expired, they do not become available again. If earned points from a refunded purchase were already spent, the adjustment offsets other or future credits; it does not create a cash debt. Points adjustments do not remove mandatory consumer remedies or convert a cash refund into a points-only remedy.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}},{"name":"Corrections and programme changes","type":"RICH_TEXT","content":{"headline":"Corrections and programme changes","copy":"Ask through Help & requests if the ledger is wrong. Our team can make documented adjustments following review, and you can see relevant history. We may change future programme rules or pause the programme with clear notice; changes will not retrospectively rewrite completed-order rules or remove legal rights. Any decision involving suspected misuse is assessed proportionately and can be reviewed through a ticket. If the programme is permanently ended, we will communicate how outstanding usable balances are handled rather than silently deleting them.","layout":"TEXT_ONLY","ctaVisible":false,"sectionWidth":"NARROW","spacing":"COMPACT"}}]},{"slug":"faq","name":"Frequently asked questions","description":"Practical answers about Kosykin 3D-printed homewares, phone and headphone stands, coasters, custom designs, care, Australian delivery and orders.","sections":[{"name":"About Kosykin and choosing homewares","type":"FAQ","content":{"headline":"About Kosykin and choosing homewares","eyebrow":"KOSYKIN ANSWERS","items":[{"question":"What is Kosykin?","answer":"Kosykin is a homewares brand operated under Tapkin. Our focus is practical and decorative 3D-printed pieces for everyday spaces. The shop shows what is currently available; a collection name does not mean every possible item in that collection is on sale.","visible":true,"order":0,"id":"6c8f248b-a1af-433a-87a7-ebebdd2116eb"},{"question":"What kinds of home products can I find at Kosykin?","answer":"Our range can include phone stands, headphone holders, coasters and other home accessories as products are added. Check the current shop for available items and each listing for its specifications and included parts.","visible":true,"order":1,"id":"de6144b9-5b79-4ed9-8825-8e4ea5d13216"},{"question":"How do I choose a 3D-printed accessory for my home?","answer":"Start with the space, intended use, measurements and devices it needs to fit. Then check the listing’s material, care guidance, finish and any load or compatibility limits. Ask us before ordering if an important requirement is not described.","visible":true,"order":2,"id":"19f31a85-b667-4741-8188-1bdf5f276323"},{"question":"Does every Kosykin product contain NFC?","answer":"No. A 3D-printed object does not automatically include NFC, a QR code or an online profile. Only rely on those features when the individual listing says they are included.","visible":true,"order":3,"id":"982f2e80-8e78-4346-8f89-a3437b990135"},{"question":"Are products already in stock or made to order?","answer":"This varies by product and option. Use the stock and preparation information in the listing or an accepted custom quote. A stocked base item may still require preparation when you choose personalisation.","visible":true,"order":4,"id":"32662818-4ffd-4337-811d-5d437d66f825"},{"question":"Does Kosykin sell every item pictured in a collection?","answer":"Not necessarily. A collection can illustrate a theme or future range. Buy only from an active product listing with a price and available checkout options; ask if you are looking for something not yet listed.","visible":true,"order":5,"id":"c21948d4-88af-4e9d-8de0-a2d180035c78"},{"question":"Can I order a gift?","answer":"Check the product’s available options and delivery estimate, then enter the intended recipient’s delivery details correctly. Gift wrapping, notes or special packaging are included only if expressly offered, not automatically.","visible":true,"order":6,"id":"08f7ef80-0c6e-46fd-8a80-29a6b5a4898a"},{"question":"Where can I check prices and availability?","answer":"The product listing and checkout show the current price and available choices. Custom work requires an agreed quote. A search result or an AI-generated answer may contain an older price or describe an unavailable item.","visible":true,"order":7,"id":"b564903a-7f39-4346-8ea3-7812fa32fb86"}]}},{"name":"Phone stands and headphone holders","type":"FAQ","content":{"headline":"Phone stands and headphone holders","eyebrow":"KOSYKIN ANSWERS","items":[{"question":"How do I choose a phone stand that fits my phone?","answer":"Compare your phone’s size and thickness, including its case, with the stand’s stated dimensions and supported use. Check the viewing angle, support surface and cable space. Do not assume a universal fit without listing information.","visible":true,"order":0,"id":"c06b5471-34b4-4b3a-82bf-72343c00ae90"},{"question":"Will a phone stand work with a thick case?","answer":"Only if the stand’s opening or support arrangement accommodates the combined phone and case thickness. Measure the case and check the listing; contact us if no clearance is specified.","visible":true,"order":1,"id":"53d6c3d5-bdeb-4108-8e1d-4a8da95ee355"},{"question":"Can I charge my phone while it is on the stand?","answer":"A stand may leave space for a charging cable, but that depends on its design and your connector. A holder is not an electrical charger unless the listing explicitly includes one. Check cable routing and supported orientation.","visible":true,"order":2,"id":"a4fbd973-a236-4798-835b-4b9358737e2c"},{"question":"Does a phone stand support both portrait and landscape use?","answer":"Check the individual design. A stand suitable in one orientation may be less stable in another, particularly with a heavy case or cable. Use only the orientations described or confirmed for the item.","visible":true,"order":3,"id":"5cb0a1fa-3716-4e0a-8122-ce74c8a1171d"},{"question":"Can I use a phone stand for a tablet?","answer":"Do not assume a phone stand supports a larger or heavier tablet. Compare the listed supported devices, dimensions and stability requirements, or ask us about a suitable design.","visible":true,"order":4,"id":"e10c1353-85ab-40ba-8490-31f1ba91e7f2"},{"question":"What should I check before buying a headphone stand?","answer":"Check your headphones’ headband shape, width, weight and hanging height against the holder’s dimensions. Consider desk footprint, cable space and where the headphones contact the support.","visible":true,"order":5,"id":"fea727b3-1282-4b2b-82e2-76a1ab89779d"},{"question":"Can a headphone holder damage the headband?","answer":"Contact pressure depends on the headphone and holder shape. Follow your headphone manufacturer’s guidance and choose a support appropriate to its padding. We cannot promise compatibility with every headband.","visible":true,"order":6,"id":"91f4cf46-eab6-4b8d-8886-674d41bdf37c"},{"question":"Will a desk holder slide or scratch my desk?","answer":"Check whether the product includes feet, padding or a non-slip base. Keep the desk and base clean and test gently on a protected area. Accessories are included only when stated.","visible":true,"order":7,"id":"98361405-3c41-4d05-8065-539230470f43"},{"question":"Can I mount a holder on a wall or under a desk?","answer":"Only use a mounting method expressly supported by the product. Mounting hardware, adhesive suitability and load limits depend on the design and surface. A freestanding holder is not automatically suitable for mounting.","visible":true,"order":8,"id":"24f56c03-9442-4a0e-8856-011e0e97cda6"}]}},{"name":"Coasters and other home accessories","type":"FAQ","content":{"headline":"Coasters and other home accessories","eyebrow":"KOSYKIN ANSWERS","items":[{"question":"What should I look for in a 3D-printed coaster?","answer":"Check its diameter, thickness, surface, base and care instructions against your cup and furniture. Heat resistance and moisture protection depend on the specific material and design, not simply on the fact it is 3D printed.","visible":true,"order":0,"id":"0ef146ad-6e3f-4abd-8c6b-38e8be5523dd"},{"question":"Can I put a hot mug on a printed coaster?","answer":"Only use a coaster within the conditions stated for that product. A very hot cup or vessel can affect some printed plastics. If the listing does not establish suitability for your intended heat exposure, ask first.","visible":true,"order":1,"id":"f820b18e-7c39-437a-8766-fbacbf3899c2"},{"question":"Is a coaster the same as a trivet?","answer":"No. A coaster intended for a drink should not be assumed safe under hot cookware, a saucepan or an oven tray. Use a product specifically designed and described for that higher-temperature purpose.","visible":true,"order":2,"id":"88a0a9f3-55ad-43c7-87b0-fb5b5224143c"},{"question":"Will a coaster prevent every water mark on furniture?","answer":"No blanket guarantee applies. Condensation, spills, surface finish and the coaster’s design all matter. Wipe spills promptly and follow both the coaster and furniture care instructions.","visible":true,"order":3,"id":"88313898-a475-47ad-8475-5dcac865c5cf"},{"question":"Can a 3D-printed planter hold water?","answer":"Do not assume it is watertight. Check whether the listing describes it as a decorative cover, a planter with drainage or a container suitable for water, and whether a liner or saucer is needed.","visible":true,"order":4,"id":"3f807f8c-59b1-4ef1-8e2d-6e4459db7b77"},{"question":"Can a printed vase hold fresh flowers?","answer":"Only if the product is described as suitable for water or uses an appropriate liner. Some decorative vases are intended for dry arrangements. Confirm the listing before filling it.","visible":true,"order":5,"id":"308e4c6a-72db-4540-877a-b3cb4bfffb1b"},{"question":"Can I put a candle or light inside a printed decoration?","answer":"Do not expose a printed piece to flames, hot bulbs or electrical components unless the product is expressly designed and assessed for that use. Decorative appearance does not establish fire or electrical safety.","visible":true,"order":6,"id":"d3742274-55a1-40d0-8d2e-1113540765c2"},{"question":"Are printed homewares suitable for food contact?","answer":"Not automatically. The material, printing process, finish and cleanability all matter. Do not use an item for direct food contact unless its listing expressly supports that use.","visible":true,"order":7,"id":"29ffc545-ceca-4562-82dd-4cf29478e963"},{"question":"Are these accessories toys or suitable for babies?","answer":"Home accessories are not automatically toys or infant products. Keep small parts and objects not intended for children out of reach and follow the individual product’s safety information.","visible":true,"order":8,"id":"a10f0289-07c4-4018-81d5-0c38a25f1def"}]}},{"name":"Materials, finish and care","type":"FAQ","content":{"headline":"Materials, finish and care","eyebrow":"KOSYKIN ANSWERS","items":[{"question":"What is 3D printing?","answer":"3D printing creates an object from a digital model in successive layers. Shape, material, production settings and finishing affect the result. Check the individual listing for the process and finish relevant to your item.","visible":true,"order":0,"id":"c08b4b33-5dd7-4973-8895-38a345055697"},{"question":"Will my item have visible layer lines?","answer":"It can. Layer lines are a common surface feature of some printing processes. Product photos and descriptions should show the finish to expect. They do not excuse a damaged item or a material mismatch with what was described.","visible":true,"order":1,"id":"5aaff7a9-f59b-44c6-8aaa-b175a32e12db"},{"question":"What material does Kosykin use?","answer":"The material is product-specific. Check the listing or accepted quote rather than assuming every item uses PLA, PETG or the same plastic. Ask if the material information needed for your use is missing.","visible":true,"order":2,"id":"de3b01e3-9d8b-47fe-86fd-6b5952ab1027"},{"question":"Will the colour exactly match my screen?","answer":"Screen settings and lighting affect colour appearance. Listing images and colour names guide your choice, but an exact screen match is not assured. Discuss a critical colour requirement before ordering.","visible":true,"order":3,"id":"62e36bde-19f7-418d-8056-ca918de03090"},{"question":"How do I clean a 3D-printed home accessory?","answer":"Follow the product’s care instructions. Unless stated otherwise, avoid harsh chemicals, abrasive scrubbing, soaking and high heat. Ask us about the specific material before choosing a cleaning method.","visible":true,"order":4,"id":"0be0abbc-b874-49b1-85a1-88bc6460eee1"},{"question":"Can I put a printed item in a dishwasher?","answer":"Do not assume dishwasher suitability. Heat, detergent and pressure can affect some materials and finishes. Use a dishwasher only when the product’s care guidance explicitly permits it.","visible":true,"order":5,"id":"f2508d39-e98f-4a51-8167-8aa87c5b68a1"},{"question":"Can I leave a printed accessory in a hot car?","answer":"Only if the product is expressly suitable for that exposure. Some printed plastics can deform in high temperatures; an ordinary indoor accessory should not be assumed safe in a parked car.","visible":true,"order":6,"id":"900fcce3-d658-4b1d-81fa-365b664b66e0"},{"question":"Are printed products waterproof or safe outdoors?","answer":"It depends on material, construction and finish. Indoor homewares are not automatically weatherproof or watertight. Follow the listed use and ask about sunlight, rain or humidity before buying for outdoor use.","visible":true,"order":7,"id":"36af8d91-fdbb-4710-8ccb-5928380fa899"},{"question":"How much weight can a printed holder carry?","answer":"Use the specific product’s stated load guidance. Size and appearance alone are not reliable indicators of strength. Do not use a decorative accessory as a safety-critical or heavy-load component.","visible":true,"order":8,"id":"8071896c-5219-4065-82c2-1f4b32020a09"},{"question":"Are 3D-printed products biodegradable or recyclable?","answer":"Do not assume an environmental claim without product-specific information. Disposal depends on the material and local facilities; a material described as compostable may require an industrial process and may not belong in a home compost or household recycling bin.","visible":true,"order":9,"id":"74424a2a-7d22-4820-8dc2-4e2a0cb590ef"},{"question":"What should I do if an item cracks or becomes unstable?","answer":"Stop using it if it may be unsafe and open a Quality ticket with the order details and what happened. Photos help if practical. We assess the issue and your rights under Australian consumer law.","visible":true,"order":10,"id":"93cf14e5-9900-4691-8f41-b81c0bf0b57d"}]}},{"name":"Personalisation and customer designs","type":"FAQ","content":{"headline":"Personalisation and customer designs","eyebrow":"KOSYKIN ANSWERS","items":[{"question":"Can I personalise a Kosykin product?","answer":"Personalisation is available only where the listing offers it or we agree it in a custom quote. Check supported text, colours, sizes and any preview carefully before paying.","visible":true,"order":0,"id":"a2b12bb8-917e-460d-8819-5b3eed08f8b6"},{"question":"Can I send my own design or file?","answer":"Yes, you can ask us to review a design through Help & requests. We confirm the accepted submission method, format, scope and feasibility before agreeing to manufacture it. Do not assume every file can be uploaded through checkout.","visible":true,"order":1,"id":"5c245e6f-0e9a-4ada-8de8-ad6aba490060"},{"question":"Which file format do you accept?","answer":"Ask about your particular job. We confirm supported file types and size limits during review. A file extension alone does not establish that the design is printable or suitable for the intended use.","visible":true,"order":2,"id":"54abcbd9-4078-46da-8f03-27a06292cffe"},{"question":"Can you print a logo or design I found online?","answer":"Only if you have the rights or permission needed for the intended manufacture and supply, and we accept the job. Downloading a file or finding an image online does not automatically grant that permission.","visible":true,"order":3,"id":"0873f095-8153-4b33-8cc1-6a47d1c0a7a9"},{"question":"Who owns a customer design after printing?","answer":"You retain rights you own in your submitted design. You give us limited permission to handle it for the agreed job and support. Rights in any newly commissioned design work are specified in the accepted quote.","visible":true,"order":4,"id":"1e956d2c-afa4-44eb-8fe8-5320dc697583"},{"question":"Will you share my personalised item on social media?","answer":"We do not use private customer artwork or finished personalised items in public marketing without separate permission. Tell us before submission if a project has additional confidentiality requirements.","visible":true,"order":5,"id":"f48e72f5-3fe8-46a9-8147-9c7c431b785d"},{"question":"Why can two similarly sized custom prints cost different amounts?","answer":"Shape, material, colour changes, print time, finishing, quantity and design work can affect cost. We review the requirements and agree a quote rather than pricing only by size.","visible":true,"order":6,"id":"d533601a-7747-44c4-8f03-f2176814b5dc"},{"question":"Can I approve a proof before a custom item is made?","answer":"Ask about the proof or approval process for your job. Where a proof is agreed, check text, dimensions and layout before approving. A render is a guide and does not establish an exact surface finish.","visible":true,"order":7,"id":"def0dd13-bd9d-4d9b-8c30-f2914a8a13ff"},{"question":"Can I change a spelling mistake after ordering?","answer":"Submit an Order change ticket promptly. A correction is normally easier before preparation or manufacturing starts. We confirm whether it is possible and any agreed extra cost; do not assume a later message automatically updates the order.","visible":true,"order":8,"id":"f09e2db8-e720-4e5f-84f1-00d76913b572"},{"question":"Can I cancel a personalised order?","answer":"We accept an eligible cancellation before preparation or manufacturing starts. Submit a verified request promptly and check the ticket for confirmation. After work starts, change-of-mind cancellation is not offered; consumer guarantees still apply.","visible":true,"order":9,"id":"57ea244c-09cb-459a-8365-96f5e6fab83f"}]}},{"name":"Orders, Australian delivery and support","type":"FAQ","content":{"headline":"Orders, Australian delivery and support","eyebrow":"KOSYKIN ANSWERS","items":[{"question":"Do I need an account to order?","answer":"You may use guest checkout when purchasing is available. An account adds enabled features such as order history and saved addresses. Guests can access support by verifying their email.","visible":true,"order":0,"id":"efc7caa2-4a35-4809-8199-10a1dafc1375"},{"question":"What payment methods can I use?","answer":"Use the methods offered by the secure Stripe checkout for your order. We do not store full card details. Payment choices can vary; a logo elsewhere on the site is not a promise that a particular method is available.","visible":true,"order":1,"id":"c301daa8-17da-4cbc-82da-2e80d645a6fa"},{"question":"Are prices in Australian dollars?","answer":"Yes, the current Australian store uses AUD. Any GST applicable to the sale is included in the displayed consumer price. Delivery and selected paid options are shown before payment.","visible":true,"order":2,"id":"ed707417-db23-41ac-8f01-e509801c5c89"},{"question":"Where in Australia do you deliver?","answer":"Checkout shows services available for your address and parcel. Support for remote areas, PO boxes or parcel lockers depends on the selected carrier service. Ask before ordering if the destination needs special handling.","visible":true,"order":3,"id":"43d7f48c-1ec5-4022-841e-999a67c99794"},{"question":"Do you offer international delivery?","answer":"The current checkout is for eligible Australian addresses. Do not assume international delivery is available; contact us before making plans for an overseas destination.","visible":true,"order":4,"id":"3b27ef85-135f-4719-83dd-835feef7917b"},{"question":"How long will my order take?","answer":"Check the listing or accepted quote for preparation time and checkout for the delivery service. Production and carrier transit are separate. If a deadline matters, ask us before paying rather than relying on a general estimate.","visible":true,"order":5,"id":"7a20129f-a101-4a4a-8721-b1197960afef"},{"question":"Does a shipping label mean my parcel has been shipped?","answer":"No. A label can be created before the item is ready. Carrier collection and subsequent tracking updates indicate the delivery stage. Check your order’s tracking information.","visible":true,"order":6,"id":"1b0271ef-2321-44ce-866b-7525780c1af6"},{"question":"How can I track a Kosykin parcel?","answer":"Use the tracking link available with your order or delivery notification. Shippit and carrier updates supply progress, which can arrive later than the physical event. Contact us if information appears wrong or incomplete.","visible":true,"order":7,"id":"da59c745-f06e-4dfe-8c58-5bfc764c67e1"},{"question":"Can I change the shipping address?","answer":"Submit an Address change ticket promptly through verified support. We confirm whether the order or carrier booking can still be changed and any genuine additional cost. A requested change is not automatic.","visible":true,"order":8,"id":"073775ac-16ff-4198-8c43-69898718cbca"},{"question":"What if my parcel says delivered but I have not received it?","answer":"Check safe places and household recipients, then open a Delivery ticket with the order and tracking details. We investigate with the carrier; a delivered scan does not automatically close your claim.","visible":true,"order":9,"id":"79b2026d-d531-4c0b-8fb1-113e3dcd779f"},{"question":"What if the parcel arrives damaged?","answer":"Open a Delivery or Quality ticket describing the damage. Packaging and item photos can help if practical. We assess the appropriate remedy and reasonable return arrangements without imposing a blanket short deadline.","visible":true,"order":10,"id":"1acac70f-2c61-46bc-8e9c-b1f3feab6b19"},{"question":"How do I contact Kosykin customer service?","answer":"Use Account → Help & requests, or verify your email through the guest help route. Outgoing email notifications direct you back to the ticket and replies to those emails are not monitored. Social media is not the verified order-support channel.","visible":true,"order":11,"id":"26b55632-4565-4c2c-8a38-2ead61ed8bba"},{"question":"How quickly will you reply to my ticket?","answer":"Our initial response target is five business days, excluding weekends and store holidays in Australia/Adelaide. This is a response target, not a guarantee of resolution, and does not limit your legal rights.","visible":true,"order":12,"id":"e82d58d7-c0ec-4aa5-8824-de6f76003273"}]}},{"name":"Returns, accounts, privacy and points","type":"FAQ","content":{"headline":"Returns, accounts, privacy and points","eyebrow":"KOSYKIN ANSWERS","items":[{"question":"Can I return a product because I changed my mind?","answer":"We do not offer change-of-mind returns or exchanges after preparation or manufacturing starts. Before that stage, we accept an eligible cancellation through verified support. This does not limit rights for faulty or misdescribed items.","visible":true,"order":0,"id":"b98e8fd1-cc4c-4959-86ab-e88ea3612231"},{"question":"Do custom products still have consumer guarantees?","answer":"Yes. Personalisation, made-to-order production and sale pricing do not remove applicable Australian consumer guarantees. Tell us through Help & requests if the item is faulty, unsafe or materially different from the agreed description.","visible":true,"order":1,"id":"37ed84d2-4106-4f62-885a-b82c287facd3"},{"question":"Do I need original packaging for a faulty-product return?","answer":"No. You do not need original packaging to exercise consumer guarantee rights. Contact us for the return process and confirmed address, and provide reasonable proof of purchase.","visible":true,"order":2,"id":"70d4c5fc-18ae-4746-8776-0d6e0880c633"},{"question":"Who pays return postage for a faulty item?","answer":"Where a fault is confirmed, we reimburse reasonable return postage and arrange or cover reasonable transport for items too large or difficult to return. Contact us before sending the item so we can confirm the appropriate process.","visible":true,"order":3,"id":"47128f9f-5d48-47c1-82e5-98768ca81bd5"},{"question":"Can I save an address in my account?","answer":"Yes. Account addresses are separate from the optional remembered details stored on a guest’s browser. Keep saved addresses up to date and check the selected address on each order.","visible":true,"order":4,"id":"704517f0-fd1e-4734-82c4-2a66f1cab186"},{"question":"Can I update my personal details?","answer":"You can edit permitted profile details and saved addresses in your account. Your login email is not directly editable there; use verified support for email or identity issues.","visible":true,"order":5,"id":"785cadfa-5b97-4243-8dde-66a39f425891"},{"question":"What does Remember my details do without an account?","answer":"When offered and selected, it stores contact and delivery details in that browser for up to 90 days under the current setting, without card details. It does not create an account. Use Forget saved details or clear site storage to remove them.","visible":true,"order":6,"id":"119b4549-413b-435c-8368-d78d624b5d4b"},{"question":"Does choosing an address suggestion guarantee delivery?","answer":"No. Suggestions help fill the form but you must check unit numbers, suburb, postcode and the final address. Available delivery is still calculated at checkout. Manual address entry remains available.","visible":true,"order":7,"id":"74dd71ff-ed73-43d2-8de9-09234c1d1746"},{"question":"How do I request my account data or deletion?","answer":"Use the available account data controls or a Privacy ticket. We verify identity and review deletion requests; some order, tax, security or dispute records may need to be retained. A request does not immediately erase all records.","visible":true,"order":8,"id":"247ac316-a56e-443a-8208-4e2d92dd54d5"},{"question":"Can I decline analytics and advertising tracking?","answer":"Yes. Use Privacy & cookie settings to decline or change optional choices. This does not prevent buying or getting support. Optional providers run only when enabled and the relevant consent has been given.","visible":true,"order":9,"id":"6bd936e9-198b-4aab-86c2-a0f7a9cf1f7a"},{"question":"Can guest purchases earn points?","answer":"When the programme is enabled and the order is eligible, guest purchases can earn after confirmed payment. Claim through a verified account using the purchase email. Older orders are not automatically backfilled.","visible":true,"order":10,"id":"8477ed59-42fe-45a4-8153-0751419bb24d"},{"question":"How much are points worth?","answer":"Check the current account and checkout rules. The initial setting earns one point per A$1 of eligible merchandise after discounts, excludes shipping, and redeems 100 points for A$2 with a 100-point minimum and a 10% merchandise discount cap. Rules for future purchases may change.","visible":true,"order":11,"id":"4d571931-92de-4caa-8845-0508218a5e3e"},{"question":"Can I use points with a discount code?","answer":"Only if the current programme rules allow combination. The initial setting does not stack points with promotional discounts. Check the option and final amount shown at checkout before paying.","visible":true,"order":12,"id":"2e50b62d-d74a-45b6-8a92-16dd0c3fbb03"},{"question":"When do my points expire?","answer":"Check each award’s expiry in your account. The initial setting is 12 calendar months from confirmed payment. A refunded or released reservation does not extend the original expiry.","visible":true,"order":13,"id":"a338fd0a-1e1b-424d-8186-f947b7b402ba"},{"question":"What happens to points if I get a refund?","answer":"Confirmed refunds proportionally reverse earned points and restore redeemed points with their original expiry, so expired points are not revived. Already spent earnings can offset other or future credits. See Customer points for the cash-refund calculation.","visible":true,"order":14,"id":"fc68e909-8b46-47f3-8ab1-bd894b5a5bc3"},{"question":"Can I use Kosykin points at Tapkin?","answer":"No automatic cross-brand redemption is offered. Customer points are scoped to the store that issued them, even though the brands use a shared platform.","visible":true,"order":15,"id":"a816aa0c-9a16-4083-8ef9-ec310b9e0bc0"}]}},{"name":"Researching products with search and AI","type":"FAQ","content":{"headline":"Researching products with search and AI","eyebrow":"KOSYKIN ANSWERS","items":[{"question":"Where can I buy 3D-printed phone stands in Australia?","answer":"You can check Kosykin’s current shop for available designs and Australian delivery options. Compare dimensions, material, care, price and availability before choosing; this answer does not mean every type of stand is currently stocked.","visible":true,"order":0,"id":"ff4769f1-8e91-42a5-82e4-81179132d9c0"},{"question":"What is the best phone stand for my desk?","answer":"The right stand depends on your phone and case, preferred angle, cable arrangement, desk space and stability needs. Compare those requirements with a current listing rather than relying on a universal best-product claim.","visible":true,"order":1,"id":"b2da3b1e-a942-4cfe-867b-b99d8d8c9069"},{"question":"How can I compare a 3D-printed holder with another material?","answer":"Compare the actual products’ dimensions, support shape, finish, care, load guidance and intended environment. A material name alone does not establish durability or suitability. Use specific evidence from each listing.","visible":true,"order":2,"id":"a57fcf35-702c-41ff-8723-8bca686440cb"},{"question":"What should I tell an AI assistant when looking for home accessories?","answer":"State the use, measurements, device or cup size, budget, environment and delivery location. Then verify suggested products against their current seller listings and ask the seller about any missing safety or compatibility information.","visible":true,"order":3,"id":"b0800b5a-b10e-42be-80d6-5cc33189db2f"},{"question":"Can I rely on a ChatGPT, Gemini or Claude answer about a Kosykin product?","answer":"Use it as a starting point, then verify the current listing, price, material, availability and policies on our site. AI answers may be outdated or mistaken, and we do not promise that any assistant will recommend or accurately describe us.","visible":true,"order":4,"id":"f803c9e5-5025-4340-86c7-e597b0282bd6"},{"question":"How do I ask about a home accessory that is not listed yet?","answer":"Open a General ticket with the intended use and measurements, without unnecessary private information. We can tell you whether a listed item or a reviewed custom request may suit; a request does not guarantee a new product or accepted job.","visible":true,"order":5,"id":"c8489a7b-369a-4eb5-86bf-44c25c8e6777"}]}}]}]$content$::jsonb) LOOP
    INSERT INTO "ContentPage" (id, "storeId", kind, slug, name, status, "showInFooter", "navigationOrder", "seoTitle", "seoDescription", indexable, "createdAt", "updatedAt")
    VALUES (gen_random_uuid(), store_id, CASE WHEN page->>'slug' = 'faq' THEN 'CAMPAIGN'::"ContentPageKind" ELSE 'LEGAL'::"ContentPageKind" END,
      page->>'slug', page->>'name', 'PUBLISHED', true, 500 + page_position, (page->>'name') || ' | Kosykin', page->>'description', true, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
    ON CONFLICT ("storeId", slug) DO UPDATE SET status = 'PUBLISHED', "showInFooter" = true,
      kind = EXCLUDED.kind, "seoTitle" = EXCLUDED."seoTitle", "seoDescription" = EXCLUDED."seoDescription", indexable = true, "updatedAt" = CURRENT_TIMESTAMP;
    SELECT id INTO page_id FROM "ContentPage" WHERE "storeId" = store_id AND slug = page->>'slug';
    IF page->>'slug' <> 'faq' THEN
      UPDATE "LandingPageSection" SET visible = false, "updatedAt" = CURRENT_TIMESTAMP WHERE "pageId" = page_id AND "storeId" = store_id;
    END IF;
    SELECT COALESCE(max("sortOrder") + 1, 0) INTO position FROM "LandingPageSection" WHERE "pageId" = page_id;
    FOR section IN SELECT value FROM jsonb_array_elements(page->'sections') LOOP
      IF section->>'type' = 'FAQ' THEN
        SELECT jsonb_agg(item ORDER BY (item->>'order')::integer) INTO faq_items
        FROM jsonb_array_elements(section->'content'->'items') item
        WHERE NOT EXISTS (
          SELECT 1 FROM "LandingPageSection" old,
            LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(old.content->'items') = 'array' THEN old.content->'items' ELSE '[]'::jsonb END) previous
          WHERE old."pageId" = page_id AND old.type = 'FAQ'
            AND lower(regexp_replace(previous->>'question', '[^a-zA-Z0-9]+', ' ', 'g')) = lower(regexp_replace(item->>'question', '[^a-zA-Z0-9]+', ' ', 'g'))
        );
        IF faq_items IS NULL THEN CONTINUE; END IF;
        section := jsonb_set(section, '{content,items}', faq_items);
      END IF;
      INSERT INTO "LandingPageSection" (id, "storeId", "pageId", type, name, visible, "sortOrder", content, "createdAt", "updatedAt")
      VALUES (gen_random_uuid(), store_id, page_id, (section->>'type')::"LandingSectionType", section->>'name', true, position, section->'content', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
      position := position + 1;
    END LOOP;
    page_position := page_position + 1;
  END LOOP;
END $phase6$;
